{"command":"./.venv/Scripts/python.exe -c "
import sys, time
sys.path.insert(0, 'scripts')
from patchright.sync_api import sync_playwright
from config import BROWSER_PROFILE_DIR, STATE_FILE
from browser_utils import BrowserFactory

with sync_playwright() as p:
    ctx = BrowserFactory.launch_persistent_context(
        p, headless=True, user_data_dir=str(BROWSER_PROFILE_DIR), state_file=str(STATE_FILE)
    )
    page = ctx.new_page()
    page.goto('https://mp.toutiao.com/profile_v4/graphic/articles', wait_until='domcontentloaded', timeout=30000)
    time.sleep(3)

    # Check tabs on the page
    tabs = page.evaluate('''() => {
        return Array.from(document.querySelectorAll('.byte-tabs-header-title, [class*=\"tab\"]'))
            .map(el => el.innerText.trim())
            .filter(t => t.length > 0 && t.length < 15);
    }''')
    print('Available tabs:', tabs[:10])

    # Click draft tab
    draft_tab = page.locator('text=草稿').first
    if draft_tab.is_visible():
        draft_tab.click()
        time.sleep(2)
        draft_titles = page.evaluate('''() => {
            const items = document.querySelectorAll('.byte-table-row, tr, [class*=\"article\"]');
            return Array.from(items).map(el => (el.innerText || '').split('\\n')[0].trim()).filter(t => t.length > 3);
        }''')
        print('Drafts found:', draft_titles[:5])
    else:
        print('Draft tab not immediately found by locator.')
    ctx.close()
""}
